// The verification log is written from the archive rather than by hand, so a
// story and the row that vouches for it cannot drift apart. The titles and the
// episodes come from `src/data/records/*.chronicle.ts`; the wiki page and the
// note come from `chronicle-sources.mjs`, which is the only part a human keeps.
//
// Run it with `npm run docs:chronicle`. The output is already shaped the way
// Prettier wants it, so `format:check` passes on a freshly generated file.
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
// eslint-disable-next-line n/no-unsupported-features/node-builtins -- The archive is TypeScript with a `~/` alias and extensionless imports; a resolve hook is the only way for a plain Node script to read the very modules the site ships, and `engines` already pins Node >= 24.18.
import { registerHooks } from 'node:module'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath, pathToFileURL } from 'node:url'

import { CHRONICLE_SOURCES } from './chronicle-sources.mjs'

/** The repository root, one level above this script. */
const ROOT = path.resolve(import.meta.dirname, '..')

/** Where the rendered log is written. */
export const DOC_PATH = path.join(ROOT, 'docs', 'chronicle-verification.md')

/**
 * The file a failed import was reaching for, without its extension.
 * @param {string} specifier The specifier, already resolved through the alias.
 * @param {string | undefined} parent The importing module's URL.
 * @returns {null | string} The path, or `null` for a package specifier.
 */
function fileFor(specifier, parent) {
  if (specifier.startsWith('file:')) {
    return fileURLToPath(specifier)
  }

  if (parent !== undefined && specifier.startsWith('.')) {
    return path.resolve(path.dirname(fileURLToPath(parent)), specifier)
  }

  return null
}

/**
 * Teaches this process the two things the archive's own imports assume: that
 * `~/` means `src/`, and that a specifier with no extension names a `.ts` file.
 * @returns {void}
 */
function registerArchiveResolution() {
  registerHooks({
    resolve(specifier, context, nextResolve) {
      const aliased =
        specifier.startsWith('~/') ?
          pathToFileURL(path.join(ROOT, 'src', specifier.slice(2))).href
        : specifier

      try {
        return nextResolve(aliased, context)
      } catch (error) {
        const file = fileFor(aliased, context.parentURL)

        if (file === null || !existsSync(`${file}.ts`)) {
          throw error
        }

        return nextResolve(pathToFileURL(`${file}.ts`).href, context)
      }
    },
  })
}

/** The preamble: how the log is made, and what the tests already hold. */
const PREAMBLE = `# Chronicle verification

<!-- Generated by \`npm run docs:chronicle\`. Edit the stories in
     \`src/data/records/*.chronicle.ts\` and the sources in
     \`scripts/chronicle-sources.mjs\`, then regenerate. -->

Every story in a character's chronicle (\`chronicle\` in the dossiers, filed in
\`src/data/records/<saga>.chronicle.ts\`) was checked against the One Piece Wiki
(onepiece.fandom.com) twice: once as it was written and once more by an
independent pass that re-read every episode against the character's \`/History\`
page (which cites each event as \`{{Qref|…|ep=N}}\`) and the episode page named in
the table, whose summary settles whether the event is complete by the end of
that episode. Where the second pass disagreed with the first, the story was
moved or rewritten; the note says what changed.

The first batch — the twelve chronicles of the crew, Shanks and Ace — was
written on 2026-09-15 and re-verified on 2026-09-19. The Dressrosa batch —
Kaido's chronicle, and the Punk Hazard and Dressrosa stories the twelve were
missing — was written and re-verified on 2026-09-20. The Summit War batch —
Law's, Rayleigh's, Borsalino's, Sakazuki's and Sabo's chronicles, and the
Summit War stories the twelve were missing — was written and re-verified on
2026-09-20. The Thriller Bark batch — Gecko Moria's chronicle, and the
Thriller Bark stories the twelve were missing — was written and re-verified
on 2026-09-20.

The rule is the one the \`status\` field already follows: **the episode filed is
the first one at whose end the viewer knows everything the story says**, with or
without a line saying it. Where a scene and its confirmation fall in different
episodes, the later one is filed. A too-early episode shows a story to a reader
who has not reached it, which is the one thing the site exists to prevent; a
too-late one only keeps it covered a little longer, and a few are filed late on
purpose, as the notes say.

Two further rules hold for every story, and the data tests
(\`src/data/characters.test.ts\`, "the chronicles") enforce what can be enforced:

- the first story sits at the character's own \`revealedAtEpisode\`, so the band
  never appears because something has happened;
- a story names only characters filed no later than its own episode, linked with
  a \`[[id]]\` marker or in plain words.

\`scripts/chronicle-verification.test.mjs\` holds the last rule this file can be
held to: every story below has a row, and every row below has a story.
`

/** The table's columns, in order. */
const COLUMNS = [
  'Entry (en title)',
  'Episode',
  'Fandom page that settles it',
  'Note',
]

/** The one right-aligned column, because an episode is a number. */
const NUMERIC = 1

/**
 * One markdown table, its columns padded the way Prettier pads them.
 * @param {string[][]} rows One array of cells per story.
 * @returns {string} The table, without a trailing newline.
 */
function table(rows) {
  const widths = COLUMNS.map((heading, index) =>
    Math.max(heading.length, ...rows.map((row) => row[index]?.length ?? 0)),
  )

  const pad = (text, index) => {
    const width = widths[index] ?? 0

    return index === NUMERIC ? text.padStart(width) : text.padEnd(width)
  }

  const rule = widths.map((width, index) =>
    index === NUMERIC ? `${'-'.repeat(width - 1)}:` : '-'.repeat(width),
  )

  return [COLUMNS, rule, ...rows]
    .map(
      (row) => `| ${row.map((cell, index) => pad(cell, index)).join(' | ')} |`,
    )
    .join('\n')
}

/**
 * The chronicled characters in the order the log lists them: the featured
 * order, which the signal book and `CHRONICLED_IDS` already use, then route
 * order for anyone chronicled but not featured.
 * @param {object} archive The loaded `~/data/characters` module.
 * @returns {object[]} The character records, in the order to print them.
 */
function chronicled(archive) {
  const { characters, dossierOf, FEATURED_CHARACTER_IDS } = archive
  const rank = (id) => {
    const index = FEATURED_CHARACTER_IDS.indexOf(id)

    return index === -1 ? Number.MAX_SAFE_INTEGER : index
  }

  return characters
    .filter((character) => dossierOf(character)?.chronicle !== undefined)
    .map((character, order) => ({ character, order }))
    .toSorted(
      (a, b) =>
        rank(a.character.id) - rank(b.character.id) || a.order - b.order,
    )
    .map(({ character }) => character)
}

/**
 * One `##` heading and table, for one character.
 * @param {object} character The character record.
 * @param {object[]} chronicle Its stories, in episode order.
 * @returns {string} The section, without a trailing newline.
 */
function section(character, chronicle) {
  const sources = CHRONICLE_SOURCES[character.id] ?? {}
  const rows = chronicle.map((story) => {
    const source = sources[story.episode]

    if (source === undefined) {
      throw new Error(
        `No verification source for ${character.id} at episode ${story.episode}: add it to scripts/chronicle-sources.mjs.`,
      )
    }

    return [
      story.value.title.en,
      String(story.episode),
      source.source,
      source.note,
    ]
  })

  const heading = `## ${character.name.en} (\`${character.id}\`, threshold ep ${character.revealedAtEpisode})`

  return `${heading}\n\n${table(rows)}`
}

/**
 * The whole document, as it should sit on disk.
 * @returns {Promise<string>} The rendered markdown.
 */
export async function render() {
  registerArchiveResolution()

  const archive = await import(
    pathToFileURL(path.join(ROOT, 'src', 'data', 'characters.ts')).href
  )
  const sections = chronicled(archive).map((character) =>
    section(character, archive.dossierOf(character).chronicle),
  )

  return `${[PREAMBLE.trimEnd(), ...sections].join('\n\n')}\n`
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const rendered = await render()
  const before = existsSync(DOC_PATH) ? readFileSync(DOC_PATH, 'utf8') : ''

  writeFileSync(DOC_PATH, rendered)
  console.log(
    rendered === before ?
      'docs/chronicle-verification.md is already up to date.'
    : 'docs/chronicle-verification.md rewritten.',
  )
}
